    BigInt numPart = BigInt.parse(subStr);

    if (numPart != BigInt.zero) {
      BigInt powerFactor = BigInt.one;
      for (BigInt pow in powersOfBase.reversed.take(lenP)) {
        rem += (numPart * powerFactor) % p;
        powerFactor *= p;
      }
    }
    pos++;
  }

  return rem.compareTo(BigInt.zero) > 0 ? rem.toInt() : p + rem.toInt();
}

