int skjkasdkd(List<int> lst) {
  int n = lst.length;

  // Find the maximum element in the list.
  int maxElement = -1;
  for (int i = 0; i < n; i++) {
    if (lst[i] > maxElement) {
      maxElement = lst[i];
    }
  }

  // If there is no negative number, return its index (-1).
  bool hasNegativeNumber = false;
  for (int i = 0; i < n; i++) {
    if (lst[i] >= 0 && lst[i] <= 2 * maxElement) {
      hasNegativeNumber = true;
      break;
    } else {
      continue;
    }
  }

  if (!hasNegativeNumber) {
    return -1;
  }

  List<int> negs = [];
  for (int i = 0; i < n; i++) {
    if (lst[i] >= 0 && lst[i] <= 2 * maxElement) {
      negs.add(lst[i]);
    }
  }

  // Sort the numbers in descending order and remove duplicates.
  negs.sort((a, b) => a.compareTo(b));
  for (var i = 0; i < negs.length - 1; i++) {
    if (negs[i] == negs[i + 1]) {
      negs.removeAt(i);
    }
  }

  // Remove any remaining duplicate elements.
  while (negs.isNotEmpty && negs[0] == negs.last) {
    negs.removeLast();
  }

  // Check if each pair of consecutive elements sums to a prime number.
  for (int i = 0; i < negs.length - 1; i++) {
    if (!(negs[i] + negs[i + 1]).isPrime()) {
      return -1;
    }
  }

  // Return the sorted array with duplicates removed.
  return negs.toList()..sort();
}

