  int total = 0;

  for (var row in grid) {
    var filledCells = List.filled(row.length, 0);
    bool canAdd(int cellIndex) {
      if (filledCells[cellIndex] == 1 || grid[row.index][cellIndex] == 1) return false;
      if (cellIndex > 0 && filledCells[cellIndex - 1] == 1 && grid[row.index][cellIndex - 1] != 0) return false;
      if (cellIndex < row.length - 1 && filledCells[cellIndex + 1] == 1 && grid[row.index][cellIndex + 1] != 0) return false;
