      final validCellIndices = [for (int i = 0; i < row.length; i++) where canAdd(i)].toList();
      if (validCellIndices.isEmpty) break;

      // If the number of available cells exceeds capacity, we must stop.
      if (validCellIndices.length >= capacity) { 
        break;
      }

      // Find a cell that is adjacent to an already filled cell or to a boundary with no further extension possible.
      late int nextFilledCellIndex;
      for (final index in validCellIndices) {
