            filledCells[index + 1] == 1 ||
                (index + 1 < row.length && !canAdd(index + 1));

        // Choose first cell satisfying any adjacency condition.
        if (hasLeftNeighborCondition()) {
          nextFilledCellIndex = index;
          break;
        } else if (hasRightNeighborCondition()) {
          nextFilledCellIndex = index;
          break;
        }
      }

      // Fill this selected cell.
      filledCells[nextFilledCellIndex] = 1;
      total++;

      // Stop filling once we reach capacity.
      if (total >= capacity) return total;
    }
  }

  return total;
}

