int levenshtein(String s1, String s2) {
  List<int> prevRow = [0..s2.length + 1];
  List<int> currRow = [0..s2.length + 1];

  for (int i = 0; i <= s1.length; i++) {
    currRow[0] = i;
    for (int j = 1; j <= s2.length; j++) {
      if (i == 0 || j == 0) {
        currRow[j] = Math.max(i, j);
      } else if (s1[i - 1].toLowerCase() == s2[j - 1]) {
        currRow[j] = prevRow[j - 1];
      } else {
        currRow[j] = Math.min(prevRow[j], currRow[j - 1]) + 1;
      }
    }
    prevRow = currRow;
  }
  return prevRow[s2.length];
}

