  final vowels = {'a', 'e', 'i', 'o', 'u'};

  int closestIndex = -1;
  String closestChar = '';

  for (int i = 0; i < word.length; i++) {
    if (vowels.contains(word[i])) {
      closestIndex = i;
      closestChar = word[i];
      break; // Stop at the first vowel found
    } else {
      if (closestIndex == -1 || abs(i - closestIndex) <= abs(word.length - 1 - closestIndex)) {
        closestIndex = i;
        closestChar = word[i];
      }
    }
  }

  return closestChar.isEmpty ? '' : closestChar;
}

