  if (game.length != guess.length) {
    throw ArgumentError('Game and guess lists must have the same length.');
  }

  int bulls = 0; // Number of correct digits in their exact positions.
  int cows = 0;   // Correct digits that are not in their original position.

  for (int i = 0; i < game.length; ++i) {
    final currentGuessDigit = guess[i];

    // Check if it's a bull first. If so, increment `bulls` and don't count as cow later.
    if (currentGuessDigit == game[i]) {
      bulls++;
    } else {
      // Look for this digit elsewhere to possibly form a cow.
      bool isCow = false;
      for (int j = 0; j < game.length; ++j) {
        if (guess[j] == game[i] && j != i) {
          cows++;
          isCow = true;
          break;
        }
      }
    }
  }

  return [bulls, cows];
}

