  int score1 = 0; // Number of correct digits in the right position.
  int score2 = 0; // Number of correct digits in the wrong position.

  for (int i = 0; i < game.length; i++) {
    if (game[i] == guess[i]) {
      score1++;
    } else {
      score2 += _countOccurrences(guess, game[i]);
    }
  }

  return [score1, score2];
